INSERT INTO `mingyan` VALUES (1,'救救我啊奥特曼，哪怕你只能撑三分钟…'),(2,'无言独上西楼，月如钩。寂寞梧桐深院锁清秋。'),(3,'此情无计可消除，才下眉头，却上心头。'),(4,'忘羡一曲远，曲终人不散。'),(5,'不要想，去感受。'),(6,'三十功名尘与土，八千里路云和月。'),(7,'人生如逆旅，我亦是行人。'),(8,'参差荇菜，左右流之。窈窕淑女，寤寐求之。'),(9,'危楼高百尺，手可摘星辰。 '),(10,'哪怕是打断你的手脚，也要把你带回去。'),(11,'绚烂如繁樱，瞬息绽放后凋落。 花以香为证，曾美至惊心动魄。'),(12,'踏长风破万里浪 '),(13,'人们总是希望付出最少的，获得最好的。'),(14,'暗恋不会窥见天光，青梅抵不过天降，永远没有旧情复燃破镜重圆。 '),(15,'我的唯一抉择，成为我宇宙的真理！'),(16,'对我而言，只是短短的五百年。对他而言，却是数之不尽的轮回！'),(17,'孤独不是一种脾性，而是一种无奈。'),(18,'Discover, Create and Use. '),(19,'你们认为没有路，是因为没有学会不择手段。 '),(20,'不管明天会发生什么，请牢记住今天。  '),(21,'旅行的意义在于找到自己，而非浏览他人。'),(22,'活的不快乐，本质上源于自己的无能。 '),(23,'髣髴兮若轻云之蔽月，飘飖兮若流风之回雪。'),(24,'我们在年少时并不知道，有些乐章一旦开始，唱的就是曲终人散。 '),(25,'不用羡慕，你也是太阳。'),(26,'不管明天会发生什么，请牢记住今天。 '),(27,'我身上早已烙下沉默燃烧后遗留下来的哀愁。'),(28,'我的手机明明没有坏掉，可是她为什么没给我打电话呢？'),(29,'不要用其他人当作走向死亡怀抱的借口！'),(30,'我妄想能改变命运，可终究不离此痛。'),(31,'不管你说再多的慌，只有自己的内心，是无法欺骗的啊。'),(32,'甲之蜜糖，乙之砒霜。'),(33,'我所理解的生活就是和喜欢的一切在一起。'),(34,'弱小和无知不是生存的障碍，傲慢才是。'),(35,'一草一千秋，一花一世界。 '),(36,'人啊...想要保护重要东西的时候，就真的能变得很坚强。'),(37,'MAKE OUR DREAMS ALIVE  '),(38,'月落乌啼霜满天，江枫渔火对愁眠。'),(39,'叶え！私たちの夢ー。'),(40,'“做到最牛”就是我所订下的每日标准，不管到哪儿都是。'),(41,'温柔正确的人总是难以生存，因为这世界既不温柔，也不正确。'),(42,'不幸的人最怕别人说他们的幸福。 '),(43,'真実はいつもひとつ！ '),(44,'さあ、始めようか。(那么，游戏开始吧。)  '),(45,'与绝望~和睦相处。'),(46,'犹豫就会败北，果断就会白给。'),(47,'宇宙是蚂蚁的梦。 '),(48,'赤锋矛，不朽盾，斩尽仙王灭九天！'),(49,'粉色蓝宝石的宝石语是「献给弱者的正义」。');
/*!40000 ALTER TABLE `mingyan` ENABLE KEYS */;
UNLOCK TABLES;

